(3484802, 486027, 73633, '<td valign="top">Love the idea and the colouring but the lighting on your model is a bit dark and I would have liked to hace seen more of the expression.</td>', 'Love the idea and the colouring but the lighting on your model is a bit dark and I would have liked to hace seen more of the expression.', '2007-03-24 04:21:04.000000', NULL, 1),
(3484803, 485196, 73633, '<td valign="top">Interesting.</td>', 'Interesting.', '2007-03-24 04:21:51.000000', NULL, 1),
(3484805, 486498, 73633, '<td valign="top">Love the contrasts and the textures of the face. Maybe the crop is just slightly too tight. Would have liked to have seen slightly more of the phone!</td>', 'Love the contrasts and the textures of the face. Maybe the crop is just slightly too tight. Would have liked to have seen slightly more of the phone!', '2007-03-24 04:24:04.000000', NULL, 1),
(3484881, 484996, 69183, '<td valign="top">This is so small I couldn''t really tell whether he had a cellphone or not without getting my nose pressed up to the monitor.</td>', 'This is so small I couldn''t really tell whether he had a cellphone or not without getting my nose pressed up to the monitor.', '2007-03-24 07:48:23.000000', NULL, 1),
(3484884, 486356, 69183, '<td valign="top">This didn''t do it for me. No one''s *using* the cellphone, and the bottom is cropped I don''t see why it was cropped like that.</td>', 'This didn''t do it for me. No one''s *using* the cellphone, and the bottom is cropped I don''t see why it was cropped like that.', '2007-03-24 07:51:15.000000', NULL, 1),
(3484889, 486317, 69183, '<td valign="top">This is great - I love the look on the guys face. I think it''d be even better if the area below his fingers was cropped out, and possibly a little off the top too. Really make him dominate the shot.</td>', 'This is great - I love the look on the guys face. I think it''d be even better if the area below his fingers was cropped out, and possibly a little off the top too. Really make him dominate the shot.', '2007-03-24 07:53:03.000000', NULL, 1),
(3484892, 486566, 69183, '<td valign="top">Ohhhh yes. How many times have I felt like doing this? Countless times. How many times have I actually done it? Only twice. So far. Well captured :)</td>', 'Ohhhh yes. How many times have I felt like doing this? Countless times. How many times have I actually done it? Only twice. So far. Well captured :)', '2007-03-24 07:55:28.000000', NULL, 1),
(3484894, 486620, 69183, '<td valign="top">Pity that this fella is missing the top of his head. I guess it was just an unlucky shot, but it ruins it for me. Sorry.</td>', 'Pity that this fella is missing the top of his head. I guess it was just an unlucky shot, but it ruins it for me. Sorry.', '2007-03-24 07:57:10.000000', NULL, 1),
